package com.amplayer.portable;
import android.app.*;import android.content.*;import android.os.*;import android.net.Uri;import android.provider.MediaStore;import android.view.*;import android.webkit.*;import org.json.*;import java.io.*;import java.net.*;import java.nio.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;
public class RadioMemory20122Instrumentation extends Instrumentation {
 private WebView web;private ServerSocket server;private Uri local;private Activity activity;
 private WebView find(View v){if(v instanceof WebView)return (WebView)v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){WebView w=find(((ViewGroup)v).getChildAt(i));if(w!=null)return w;}return null;}
 private String js(String code)throws Exception{CountDownLatch done=new CountDownLatch(1);AtomicReference<String> value=new AtomicReference<>();runOnMainSync(()->web.evaluateJavascript(code,v->{value.set(v);done.countDown();}));if(!done.await(15,TimeUnit.SECONDS))throw new Exception("JS timeout");return value.get();}
 private void waitJS(String code)throws Exception{for(int i=0;i<100;i++){if("true".equals(js(code)))return;Thread.sleep(100);}throw new Exception("UI check failed: "+code);}
 private JSONObject status()throws Exception{return new JSONObject(PlaybackService.status());}
 private JSONObject await(String field,String value)throws Exception{for(int i=0;i<100;i++){JSONObject s=status();if(s.optJSONObject("item")!=null&&value.equals(s.getJSONObject("item").optString(field))&&s.optBoolean("playing"))return s;Thread.sleep(100);}throw new Exception("Playback wait failed "+value+" "+status());}
 private void report(String key,String value){Bundle b=new Bundle();b.putString(key,value);sendStatus(0,b);}
 private void startNative(JSONObject item)throws Exception{runOnMainSync(()->getTargetContext().startForegroundService(new Intent(getTargetContext(),PlaybackService.class).setAction("item").putExtra("item",item.toString())));}
 @Override public void onCreate(Bundle args){super.onCreate(args);start();}
 @Override public void onStart(){Bundle result=new Bundle();JSONObject original=Store.load(getTargetContext());try{
  int bytes=640000;ByteBuffer wave=ByteBuffer.allocate(44+bytes).order(ByteOrder.LITTLE_ENDIAN);wave.put("RIFF".getBytes()).putInt(36+bytes).put("WAVEfmt ".getBytes()).putInt(16).putShort((short)1).putShort((short)1).putInt(8000).putInt(16000).putShort((short)2).putShort((short)16).put("data".getBytes()).putInt(bytes);byte[] audio=wave.array();
  server=new ServerSocket(0,8,InetAddress.getByName("127.0.0.1"));Thread serving=new Thread(()->{while(!server.isClosed())try{Socket socket=server.accept();Thread client=new Thread(()->{try(Socket c=socket){BufferedReader in=new BufferedReader(new InputStreamReader(c.getInputStream()));String line;while((line=in.readLine())!=null&&!line.isEmpty()){}OutputStream out=c.getOutputStream();out.write(("HTTP/1.1 200 OK\r\nContent-Type: audio/wav\r\nContent-Length: "+audio.length+"\r\nConnection: close\r\n\r\n").getBytes());out.write(audio);out.flush();}catch(Exception ignored){}});client.setDaemon(true);client.start();}catch(Exception ignored){}});serving.setDaemon(true);serving.start();
  String base="http://127.0.0.1:"+server.getLocalPort();JSONObject a=new JSONObject().put("id","memory-a").put("name","Radio A").put("type","radio").put("country","TW").put("region","TW").put("url",base+"/a.wav"),b=new JSONObject(a.toString()).put("id","memory-b").put("name","Radio B").put("url",base+"/b.wav");
  ContentValues values=new ContentValues();values.put(MediaStore.Audio.Media.DISPLAY_NAME,"JAMPlayer-RadioMemory20122-"+System.currentTimeMillis()+".wav");values.put(MediaStore.Audio.Media.MIME_TYPE,"audio/wav");values.put(MediaStore.Audio.Media.RELATIVE_PATH,"Music/JAMPlayerTest");local=getTargetContext().getContentResolver().insert(MediaStore.Audio.Media.EXTERNAL_CONTENT_URI,values);if(local==null)throw new Exception("Local fixture failed");try(OutputStream out=getTargetContext().getContentResolver().openOutputStream(local)){out.write(audio);}JSONObject song=new JSONObject().put("name","Local music").put("type","local").put("path",local.toString()).put("playbackContext","local");
  JSONObject prefs=new JSONObject(original.toString()).put("stations",new JSONArray().put(a).put(b)).put("localFiles",new JSONArray().put(song)).put("favorites",new JSONArray()).put("playlists",new JSONArray()).put("volume",0).put("autoUpdate",false).put("localPlayMode","list").put("language","zh-Hant");for(String key:new String[]{"lastPlayed","lastRadioPlayed","lastLocalPlayed"})prefs.remove(key);Store.save(getTargetContext(),prefs.toString());
  activity=startActivitySync(new Intent(getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));runOnMainSync(()->web=find(activity.getWindow().getDecorView()));waitJS("typeof state!=='undefined'&&!!state");js("playItem(state.stations.find(x=>x.id==='memory-a'));true");await("url",a.getString("url"));
  js("clearInterval(pollTimer);pollTimer=null;true");runOnMainSync(()->getTargetContext().startService(new Intent(getTargetContext(),PlaybackService.class).setAction("next")));await("url",b.getString("url"));startNative(song);await("path",local.toString());JSONObject saved=Store.load(getTargetContext());if(!"memory-b".equals(saved.getJSONObject("lastRadioPlayed").optString("id")))throw new Exception("Native local play overwrote radio B");if(!"memory-b".equals(status().getJSONObject("lastRadioPlayed").optString("id")))throw new Exception("Native snapshot missing radio memory");report("nativeMemory","PASS real HTTP audio A -> native next B -> real local audio retains independent B memory");
  js("poll();showPage('radio');true");waitJS("state.lastRadioPlayed?.id==='memory-b'&&$('library-list').querySelector('.remembered-track')?.dataset.key==="+JSONObject.quote(b.getString("url")));if(!local.toString().equals(status().getJSONObject("item").optString("path")))throw new Exception("Radio tab started radio automatically");report("returnFocus","PASS native background change while UI polling stopped is recalled; radio tab focuses B without interrupting local audio");
  js("refreshPlayer();$('btn-loop').click();true");waitJS("state.localPlayMode==='one'&&$('sheet-backdrop').hidden&&!$('toast').hidden");if(!"one".equals(Store.load(getTargetContext()).optString("localPlayMode")))throw new Exception("Mode not saved");runOnMainSync(()->PlaybackService.seek(39700));Thread.sleep(1800);JSONObject repeated=await("path",local.toString());if(repeated.optLong("position")>5000)throw new Exception("Direct single repeat did not wrap");report("directMode","PASS button cycles directly, shows notice and applies actual native single-track repeat");
  runOnMainSync(activity::finish);Thread.sleep(300);activity=startActivitySync(new Intent(getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));runOnMainSync(()->web=find(activity.getWindow().getDecorView()));waitJS("typeof state!=='undefined'&&state.lastRadioPlayed?.id==='memory-b'");js("showPage('radio');true");waitJS("$('library-list').querySelector('.remembered-track')?.dataset.key==="+JSONObject.quote(b.getString("url")));report("restartMemory","PASS reopening activity while local audio plays retains remembered radio B and its focus");result.putString("result","PASS");
 }catch(Throwable e){result.putString("failure",e.toString());}finally{getTargetContext().stopService(new Intent(getTargetContext(),PlaybackService.class));if(activity!=null)runOnMainSync(activity::finish);if(server!=null)try{server.close();}catch(Exception ignored){}if(local!=null)getTargetContext().getContentResolver().delete(local,null,null);try{Store.save(getTargetContext(),original.toString());}catch(Exception ignored){}}finish(result.containsKey("failure")?Activity.RESULT_CANCELED:Activity.RESULT_OK,result);}
}
